def populate_inventory_locations(apps, schema_editor):
    Warehouse = apps.get_model('tenancy', 'Warehouse')
    InventoryLocation = apps.get_model('inventory', 'InventoryLocation')
    StockLevel = apps.get_model('inventory', 'StockLevel')
    StockMovement = apps.get_model('inventory', 'StockMovement')
    StockTransfer = apps.get_model('inventory', 'StockTransfer')
    StockAdjustment = apps.get_model('inventory', 'StockAdjustment')

    wh_to_loc = {}
    for wh in Warehouse.objects.all():
        loc_type = "central_warehouse" if getattr(wh, "is_default", False) else "branch_warehouse"
        loc = InventoryLocation.objects.filter(
            organization_id=wh.organization_id,
            warehouse_id=wh.id,
        ).first()
        if not loc:
            loc = InventoryLocation.objects.create(
                organization_id=wh.organization_id,
                warehouse_id=wh.id,
                name=wh.name,
                code=getattr(wh, "code", "") or f"WH-{wh.id}",
                location_type=loc_type,
                branch_id=getattr(wh, "branch_id", None),
                is_stock_holding=True,
                is_active=getattr(wh, "is_active", True),
                address=getattr(wh, "address", "") or "",
            )
        wh_to_loc[wh.id] = loc.id

    for wh_id, loc_id in wh_to_loc.items():
        StockLevel.objects.filter(warehouse_id=wh_id, location__isnull=True).update(location_id=loc_id)
        StockMovement.objects.filter(warehouse_id=wh_id, location__isnull=True).update(location_id=loc_id)
        StockTransfer.objects.filter(source_warehouse_id=wh_id, source_location__isnull=True).update(source_location_id=loc_id)
        StockTransfer.objects.filter(destination_warehouse_id=wh_id, destination_location__isnull=True).update(destination_location_id=loc_id)
        StockAdjustment.objects.filter(warehouse_id=wh_id, location__isnull=True).update(location_id=loc_id)


def reverse_populate(apps, schema_editor):
    pass


